function frame(t, p, d) {
  const sH = spr(t, 0.0, 0.9, 6);
  const s0 = spr(t, 0.4, 0.8, 6);
  const s1 = spr(t, 0.8, 0.8, 6);
  const s2 = spr(t, 1.2, 0.8, 6);
  const sM = spr(t, 1.6, 0.8, 6);
  const fill = E_OUT(clamp((t - 1.8) / 1.5));

  h.style.opacity = sH;
  h.style.transform = `translateY(${lerp(20, 0, sH)}px)`;
  f.style.opacity = sH * 0.7;
  f.style.transform = `translateY(${lerp(-10, 0, sH)}px)`;

  cards[0].style.opacity = s0;
  cards[0].style.transform = `translateY(${lerp(40, 0, s0)}px) scale(${lerp(0.95, 1, s0)})`;

  cards[1].style.opacity = s1;
  cards[1].style.transform = `translateX(${lerp(-40, 0, s1)}px)`;

  cards[2].style.opacity = s2;
  cards[2].style.transform = `translateX(${lerp(40, 0, s2)}px)`;

  m.style.opacity = sM;
  m.style.transform = `translateY(${lerp(30, 0, sM)}px)`;

  const pct = Math.floor(fill * 100);
  mb.style.width = pct + '%';
  mv.textContent = pct + '%';
}
